  function domaineDeDegats(type) {
    if (!type) return 'normal';
    return DOMAINE_PAR_TYPE_HISTORIQUE[type] || type;
  }

  function typesCompatiblesDegats(type) {
    if (!type) return ['normal'];
    const domaine = domaineDeDegats(type);
    const types = [type];
    if (domaine != type) {
      types.push(domaine);
    } else {
      (TYPES_HISTORIQUES_PAR_DOMAINE[domaine] || []).forEach(function(ancien) {
        if (!types.includes(ancien)) types.push(ancien);
      });
    }
    return types;
  }

  function estDomaineDegats(type) {
    return DOMAINES_DEGATS.has(type);
  }

