  function cofEtatLabel(etat) {
    return COF_ETATS_REFONDUS[etat] ? COF_ETATS_REFONDUS[etat].label : stringOfEtat(etat);
  }

  function sourceEtatCible(perso, etat) {
    let id = attributeAsString(perso, etat + 'Source');
    if (!id) return;
    return persoOfIdName(id, perso.token.get('pageid'));
  }

  function memoriseSourceEtat(perso, etat, source, evt) {
    if (etat != 'provoque' && etat != 'charme') return;
    if (!source || !source.token) return;
    setTokenAttr(perso, etat + 'Source', source.token.id, evt, {maxVal: nomPerso(source)});
  }

  function effaceSourceEtat(perso, etat, evt) {
    if (etat != 'provoque' && etat != 'charme') return;
    removeTokenAttr(perso, etat + 'Source', evt);
  }

  function peutVoler(perso) {
    return predicateAsBool(perso, 'volant');
  }

  function suspendVolPourAttaqueContact(perso, evt) {
    if (!getState(perso, 'volant')) return false;
    setState(perso, 'volant', false, evt);
    setTokenAttr(perso, 'volantSuspendu', 1, evt);
    sendPerso(perso, "redescend pour effectuer son attaque au contact : <b>Volant</b> est suspendu jusqu'au début de son prochain tour.");
    return true;
  }

  function restaureVolDebutTour(perso, evt) {
    if (!attributeAsBool(perso, 'volantSuspendu')) return;
    removeTokenAttr(perso, 'volantSuspendu', evt);
    if (!peutVoler(perso) || getState(perso, 'mort') || getState(perso, 'paralyse') ||
        getState(perso, 'sommeil') || getState(perso, 'endormi')) return;
    setState(perso, 'volant', true, evt);
    sendPerso(perso, "reprend son envol : <b>Volant</b> est de nouveau actif.");
  }

  function synchroniseVolantDepuisPredicat(perso, evt) {
    if (!perso || !perso.token || !peutVoler(perso)) return;

    if (attributeAsBool(perso, 'volantSuspendu')) return;
    if (getState(perso, 'volant')) return;
    evt = evt || {type:'synchronisationVolant', attributes:[], deletedAttributes:[]};
    setState(perso, 'volant', true, evt);
    return evt;
  }

  function synchroniseVolantPersonnage(charId) {
    if (!charId) return;
    let tokens = findObjs({_type:'graphic', _subtype:'token', represents:charId}) || [];
    tokens.forEach(function(token) {
      let perso = persoOfToken(token);
      if (!perso) return;
      if (peutVoler(perso)) {
        let evt = synchroniseVolantDepuisPredicat(perso);
        if (evt) addEvent(evt);
      } else if (getState(perso, 'volant') && !attributeAsBool(perso, 'volantSuspendu')) {
        let evt = {type:'synchronisationVolant', attributes:[], deletedAttributes:[]};
        setState(perso, 'volant', false, evt);
        addEvent(evt);
      }
    });
  }

  function afficherCarteEtat(perso, etat, actif) {
    let r = COF_ETATS_REFONDUS[etat];
    if (!r) return;
    let nom = nomPerso(perso);
    if (!actif) {
      sendChat('COF', '<div style="border:1px solid #555;background:#fff;padding:6px;border-radius:5px"><b>' +
        nom + '</b> : état <b>' + r.label + '</b> retiré.</div>');
      return;
    }
    let cmd = '!cof-set-state ' + etat + ' false --target ' + perso.token.id;
    let bouton = boutonSimple(cmd, 'Retirer ' + r.label);
    if (etat == 'confus') bouton += ' ' + boutonSimple('!cof-jet-confusion --target ' + perso.token.id, 'Jet de confusion');
    let source = sourceEtatCible(perso, etat);
    let sourceTxt = source ? '<br><b>Source :</b> ' + nomPerso(source) : '';
    sendChat('COF', '<div style="border:2px solid #7b1e1e;background:#fff;padding:7px;border-radius:6px">' +
      '<b>' + r.label + ' — ' + nom + '</b>' + sourceTxt + '<br>' + r.aide + '<br>' + bouton + '</div>');
  }

  const etat_de_marker = {};
  const effet_de_marker = {};

  function fullAttributeName(perso, attribute, options) {
    if (perso.token && (!options || !options.charAttr)) {
      let link = perso.token.get('bar1_link');
      if (link === '') return attribute + '_' + perso.token.get('name');
    }
    return attribute;
  }

  function tokenAttribute(personnage, name) {
    let fullName = fullAttributeName(personnage, name);
    return findObjs({
      _type: 'attribute',
      _characterid: personnage.charId,
      name: fullName
    });
  }

  function charAttribute(charId, name, option) {
    return findObjs({
      _type: 'attribute',
      _characterid: charId,
      name: name
    }, option);
  }

  function toInt(n, def) {
    let res = parseInt(n);
    if (isNaN(res)) return def;
    return res;
  }

  function attrAsInt(attr, def, defPresent) {
    if (attr.length === 0) return def;
    if (defPresent === undefined) defPresent = def;
    return toInt(attr[0].get('current'), defPresent);
  }

  function attrAsBool(attr) {
    if (attr.length === 0) return false;
    attr = attr[0].get('current');
    if (attr == '0' || attr == 'false') return false;
    if (attr) return true;
    return false;
  }

  function attrAsString(attr, def = '') {
    if (attr.length === 0) return def;
    return attr[0].get('current') + '';
  }

  function getCharId(perso, name, options) {
    let charId = perso.charId;
    if (options && options.transforme) {
      persoTransforme(perso);
      if (perso.transforme.charId) {
        if (perso.transforme.garde && perso.transforme.garde[name.toLowerCase()])
          return charId;
        charId = perso.transforme.charId;
      }
    }
    return charId;
  }

  function attributesInsensitive(perso, name, options) {
    return charAttribute(getCharId(perso, name, options), name, {
      caseInsensitive: true
    });
  }

  function ficheAttribute(personnage, name, def, options) {
    let attr = attributesInsensitive(personnage, name, options);
    if (attr.length === 0) return def;
    return attr[0].get('current');
  }

  function ficheAttributeMax(personnage, name, def, options) {
    let attr = attributesInsensitive(personnage, name, options);
    if (attr.length === 0) return def;
    return attr[0].get('max');
  }

  function ficheAttributeAsInt(perso, name, def, options) {
    let attr = attributesInsensitive(perso, name, options);
    let res = attrAsInt(attr, def);
    if (options && options.transforme &&
      perso.transforme.gardeMeilleur && perso.transforme.gardeMeilleur[name]) {
      attr = attributesInsensitive(perso, name);
      let orig = attrAsInt(attr, def);
      res = Math.max(def, orig);
    }
    return res;
  }

  function exactCharAttribute(charId, name) {
    let exact = findObjs({
      _type: 'attribute',
      _characterid: charId,
      name: name
    }) || [];
    if (exact.length > 0) return exact[0];

    let legacy = findObjs({
      _type: 'attribute',
      _characterid: charId,
      name: name
    }, {
      caseInsensitive: true
    }) || [];
    return legacy.length > 0 ? legacy[0] : undefined;
  }

  function setSheetAttrs(charId, values) {
    let currentValues = {}, maxValues = {};
    Object.keys(values || {}).forEach(function(name) {
      if (name.endsWith('_max')) maxValues[name.substring(0, name.length - 4)] = values[name];
      else currentValues[name] = values[name];
    });
    Object.keys(currentValues).forEach(function(name) {
      let attr = exactCharAttribute(charId, name);
      if (!attr) attr = createObj('attribute', {characterid: charId, name: name, current: currentValues[name]});
      else if (attr.setWithWorker) attr.setWithWorker({current: currentValues[name]});
      else attr.set('current', currentValues[name]);
    });
    Object.keys(maxValues).forEach(function(name) {
      let attr = exactCharAttribute(charId, name);
      if (!attr) attr = createObj('attribute', {characterid: charId, name: name, current: currentValues[name] === undefined ? '' : currentValues[name], max: maxValues[name]});
      else attr.set('max', maxValues[name]);
    });
  }

  function ficheResourceInfo(perso, name, defaultCurrent, defaultMax) {
    let attr = exactCharAttribute(perso.charId, name);
    if (!attr) {
      return {
        attribut: undefined,
        current: defaultCurrent,
        max: defaultMax,
        missing: true
      };
    }
    let current = parseInt(attr.get('current'));
    let max = parseInt(attr.get('max'));
    if (isNaN(max) || max < 0) max = defaultMax;
    if (isNaN(current)) current = defaultCurrent;
    if (current < 0) current = 0;
    if (max >= 0 && current > max) current = max;
    return {
      attribut: attr,
      current: current,
      max: max,
      missing: false
    };
  }

  function manaInfo(perso) {
    return ficheResourceInfo(perso, 'pm', 0, 0);
  }

  function ficheAttributeAsBool(personnage, name, def, options) {
    let attr = attributesInsensitive(personnage, name, options);
    if (attr.length === 0) return def;
    return attrAsBool(attr);
  }

  function attributeAsInt(personnage, name, def, defPresent) {
    let attr = tokenAttribute(personnage, name);
    return attrAsInt(attr, def, defPresent);
  }

  function attributeAsBool(personnage, name) {
    let attr = tokenAttribute(personnage, name);
    return attrAsBool(attr);
  }

  function attributeAsString(personnage, name, def = '') {
    let attr = tokenAttribute(personnage, name);
    return attrAsString(attr, def);
  }

  function charAttributeAsInt(perso, name, def, defPresent) {
    let attr = charAttribute(perso.charId, name);
    return attrAsInt(attr, def, defPresent);
  }

  function charAttributeAsBool(perso, name) {
    let attr = charAttribute(perso.charId, name);
    return attrAsBool(attr);
  }

  function assignPredicate(pred, name, val) {
    if (pred[name]) {
      if (!Array.isArray(pred[name])) pred[name] = [pred[name]];
      pred[name].push(val);
    } else pred[name] = val;
  }

  function predicateOfRaw(raw) {
    let pred = {};
    let last, assign;

    let lignes = raw.split('\n');
    lignes.forEach(function (ligne) {
      let indexPredComplexe = ligne.indexOf('::');
      let indexCommentaire = ligne.indexOf('//');
      let valeurPredComplexe = '';
      if (indexPredComplexe > 0 &&
        (indexCommentaire == -1 || indexCommentaire > indexPredComplexe)) {
        valeurPredComplexe = ligne.substring(indexPredComplexe + 2);
        ligne = ligne.substring(0, indexPredComplexe);
      } else if (indexCommentaire > 0) {
        ligne = ligne.substring(0, indexCommentaire);
      }
      ligne.split(/,| /).forEach(function (p) {
        p = p.trim();
        if (p === '') return;
        if (p === ':') {
          if (last) assign = true;
          return;
        }
        let i = p.indexOf(':');
        if (i < 0) {
          if (last) {
            if (assign) {
              assignPredicate(pred, last, p);
              assign = false;
            } else pred[last] = true;
          }
          last = p;
          return;
        }

        if (i === 0) {
          if (last) {
            assignPredicate(pred, last, p.substring(1));
            last = undefined;
          } else {
            last = p.substring(1);
          }
          assign = false;
          return;
        }
        if (last) pred[last] = true;
        if (i == p.length - 1) {
          last = p.substring(0, i);
          assign = true;
        } else {
          assignPredicate(pred, p.substring(0, i), p.substring(i + 1));
          last = undefined;
          assign = false;
        }
      });
      if (last && valeurPredComplexe !== '') {
        assignPredicate(pred, last, valeurPredComplexe);
        last = undefined;
      }
    });
    if (last) pred[last] = true;
    return pred;
  }

  function charPredicateAsBool(charId, name) {
    let pred = stateCOF.predicats[charId];
    if (pred) return pred[name];
    let raw = '';
    let attr = charAttribute(charId, 'predicats_script', {
      caseInsensitive: true
    });
    if (attr.length > 0) {
      raw = attr[0].get('current');
    }
    let perso = {
      charId
    };
    let labelArmeGauche = 0;
    let labelArme = ficheAttributeAsInt(perso, 'maindroite', 0);
    let labelGauche = ficheAttribute(perso, 'maingauche', '0');
    let versionFiche = findObjs({
      _type: 'attribute',
      _characterid: charId,
      name: 'version',
    }, {
      caseInsensitive: true
    });
    if (versionFiche.length === 0) versionFiche = 0;
    else versionFiche = parseFloat(versionFiche[0].get('current'));
    if (versionFiche < 5.04) {
      let armures;
      let labelArmure = ficheAttribute(perso, 'torseequipe', '0');
      if (labelArmure && labelArmure != '-1') {
        armures = armures || listAllArmors(perso);
        let armure = armures[labelArmure];
        if (armure) {
          let rawArmure = fieldAsString(armure, 'effetarmure', '');
          if (rawArmure) raw += '\n' + rawArmure;
        }
      }
      let labelCasque = ficheAttribute(perso, 'teteequipe', '0');
      if (labelCasque && labelCasque != '-1') {
        armures = armures || listAllArmors(perso);
        let casque = armures[labelCasque];
        if (casque) {
          let rawCasque = fieldAsString(casque, 'effetarmure', '');
          if (rawCasque) raw += '\n' + rawCasque;
        }
      }
      if (typeof labelGauche == 'string' && labelGauche.startsWith('b')) {
        if (labelGauche != 'b-1') {
          armures = armures || listAllArmors(perso);
          let labelBouclier = labelGauche.substring(1);
          let bouclier = armures[labelBouclier];
          if (bouclier) {
            let rawBouclier = fieldAsString(bouclier, 'effetarmure', '');
            if (rawBouclier) raw += '\n' + rawBouclier;
          }
        }
      } else if (labelGauche != '2m') labelArmeGauche = toInt(labelGauche);
    } else {

      let armures = listAllArmors(perso);
      for (let label in armures) {
        let ar = armures[label];
        if (ar.equipearmure == '1') {
          let r = fieldAsString(ar, 'effetarmure', '');
          if (r) raw += '\n' + r;
        }
      }
      if (typeof labelGauche != 'string' ||
        (!labelGauche.startsWith('b') && labelGauche != '2m'))
        labelArmeGauche = toInt(labelGauche);
    }
    let att;
    let attaques;
    if (labelArme) {
      attaques = listAllAttacks({
        charId
      });
      let att = attaques[labelArme];
      if (att) {
        let rawArme = fieldAsString(att, 'armepredicats', '');
        if (rawArme) raw += '\n' + rawArme;
      }
    }

    if (labelArmeGauche) {
      if (!attaques) {
        attaques = attaques || listAllAttacks({
          charId
        });
        att = attaques[labelArmeGauche];
      }
      if (att) {
        let rawArme = fieldAsString(att, 'armepredicats', '');
        if (rawArme) raw += '\n' + rawArme;
      }
    }
    persoTransforme(perso);
    if (perso.transforme.charId) {
      let rawT = ficheAttribute(perso, 'predicats_script', '', optTransforme);
      if (rawT) raw += '\n' + rawT;
    }
    pred = predicateOfRaw(raw);
    stateCOF.predicats[charId] = pred;
    return pred[name];
  }

  function persoTransforme(perso) {
    if (perso.transforme) return;
    perso.transforme = {
      charId: false
    };
    let attrs = tokenAttribute(perso, 'changementDeForme');
    if (attrs.length === 0) return;
    let nomForme = attrs[0].get('current');
    let forme = findObjs({
      _type: 'character',
      name: nomForme
    });
    if (forme.length == 0) return;
    perso.transforme.charId = forme[0].id;
    let garde = attrs[0].get('max');
    if (garde) {
      perso.transforme.garde = {};
      let gardeEtMeilleur = garde.split('||');
      garde = gardeEtMeilleur[0].split(',');
      garde.forEach(function (g) {
        perso.transforme.garde[g] = true;
      });
      if (gardeEtMeilleur.length > 1) {
        perso.transforme.gardeMeilleur = {};
        let meilleur = gardeEtMeilleur[1].split(',');
        meilleur.forEach(function (m) {
          perso.transforme.gardeMeilleur[m] = true;
        });
      }
    }
  }

  function persoEstPNJ(perso, options = {}) {
    let ptest = perso;
    if (options.transforme) {
      persoTransforme(perso);
      if (perso.transforme.charId) ptest = perso.transforme;
    }
    if (ptest.pnj) return true;
    else if (ptest.pj) return false;
    const typePerso = ficheAttribute(perso, 'type_personnage', 'PJ', options);
    ptest.pnj = (typePerso == 'PNJ');
    ptest.pj = !perso.pnj;
    return ptest.pnj;
  }

  let optTransforme = {
    transforme: true
  };

  function modCarac(perso, carac, options) {
    if (perso.charId === undefined) perso = {
      charId: perso
    };
    let modCarac = modOfCarac(carac);
    let mod = 0;
    let opt = options || optTransforme;
    if (persoEstPNJ(perso, opt)) {
      switch (modCarac) {
        case 'FOR':
          mod = ficheAttributeAsInt(perso, 'pnj_for', 0, opt);
          break;
        case 'DEX':
          mod = ficheAttributeAsInt(perso, 'pnj_dex', 0, opt);
          break;
        case 'CON':
          mod = ficheAttributeAsInt(perso, 'pnj_con', 0, opt);
          break;
        case 'INT':
          mod = ficheAttributeAsInt(perso, 'pnj_int', 0, opt);
          break;
        case 'SAG':
          mod = ficheAttributeAsInt(perso, 'pnj_sag', 0, opt);
          break;
        case 'CHA':
          mod = ficheAttributeAsInt(perso, 'pnj_cha', 0, opt);
          break;
        default:
          return 0;
      }
      mod -= Math.floor(attributeAsInt(perso, 'affaiblissementde' + carac, 0) / 2);
    } else {

      let valCarac =
        ficheAttributeAsInt(perso, carac, 10, opt) - attributeAsInt(perso, 'affaiblissementde' + carac, 0);
      mod = Math.floor((valCarac - 10) / 2);
    }
    if (modCarac == 'FOR') {
      if (attributeAsBool(perso, 'mutationMusclesHypertrophies')) mod += 2;
      if (attributeAsBool(perso, 'grandeTaille')) mod += 2;
      if (attributeAsBool(perso, 'lycanthropie')) mod += 1;
    } else if (modCarac == 'DEX' && attributeAsBool(perso, 'mutationSilhouetteFiliforme')) mod += 4;
    mod += predicateAsInt(perso, 'bonus_' + modCarac, 0);
    return mod;
  }

  function forceLightingRefresh(pageId) {
    let page = getObj('page', pageId);
    if (!page) return;
    page.set('force_lighting_refresh', true);
  }

