  const listeDesRunesMortes = {
    Melianil: {
      description: "+2 en attaque et +1d6 aux DM (à tous les sorts ou aux attaques au contact avec le bâton)",
    },
    Isulys: {
      description: "une fois par tour, par une action d'attaque, peut produire un rayon d’énergie négative d’une portée de 40 mètres. Sur test d’attaque magique réussit, la victime subit [2d6 + Mod. %SAGINT] DM et doit utiliser un d12 à tous ses tests au lieu d’un d20 pendant un tour.",
    },
    Bryniza: {
      description: "permet de voir parfaitement dans le noir à une portée de 30 m, et comme dans la pénombre jusqu'à 50 m. Au prix d'une action limitée, le porteur peut utiliser le sort Détection de la magie 3 fois par jour.",
      activation: "Les yeux de %NOM deviennent d'un noir d'encre.",
      fin: "Les yeux de %NOM redeviennent normaux.",
    },
    Lizura: {
      description: "immunité au souffle de Swarathnak, à l'acide et au poison.",
      activation: "La boue noire du bâton s'écoule le long du bras de %NOM et recouvre tout son corps à l'exception des yeux.",
      fin: "La boue se retire dans le bâton, %NOM retrouve une apparence normale.",
      memeEffetQue: 'Mitrah',

    },
    Mitrah: {
      description: "RD 5 à tous les DM.",
      activation: "La boue noire du bâton s'écoule le long du bras de %NOM et recouvre tout son corps à l'exception des yeux.",
      fin: "La boue se retire dans le bâton, %NOM retrouve une apparence normale.",
      memeEffetQue: 'Lizura',
    },
  };

  const styleRuneActive =
    'display: inline-block; border-radius: 5px; padding: 0 4px; background-color: #80bf40; color: #020401;';

  function gererRunesMortes(msg) {
    let cmd = msg.content.split(' ');
    if (cmd.length < 2) {
      error("il manque l'id du personnage qui gère ses runes mortes", cmd);
      return;
    }
    let perso = persoOfId(cmd[1]);
    if (perso === undefined) return;
    if (!predicateAsBool(perso, 'batonDesRunesMortes')) {
      sendPerso(perso, "ne porte pas le bâton des runes mortes");
      return;
    }
    let niveau = ficheAttributeAsInt(perso, 'niveau', 1);
    let playerId = getPlayerIdFromMsg(msg);
    let display = startFramedDisplay(playerId, "Runes mortes", perso, {
      chuchote: true
    });
    let caracSag = "de SAG";
    if (modCarac(perso, 'intelligence') > modCarac(perso, 'sagesse'))
      caracSag = "d'INT";
    if (cmd.length > 3) {
      const evt = {
        type: "gestion des runes mortes",
      };
      addEvent(evt);
      switch (cmd[2]) {
        case 'activer':
          {
            let er = listeDesRunesMortes[cmd[3]];
            if (!er) {
              error("Rune " + cmd[3] + " non reconnue", cmd);
              break;
            }

            let runesLibres = Math.ceil(niveau / 4);
            for (let rune in listeDesRunesMortes) {
              if (attributeAsBool(perso, 'rune' + rune)) runesLibres--;
            }
            if (runesLibres < 1) {
              sendPerso(perso, "ne peut pas activer plus de runes", true);
              break;
            }
            let attr = tokenAttribute(perso, 'rune' + cmd[3]);
            if (attr.length > 0) {
              if (attr[0].get('current') == 'false') {
                let donne = attr[0].get('max');
                if (donne) {
                  sendPerso(perso, "a donné " + cmd[3] + " à " + donne + ". Impossible de l'activer.", true);
                  break;
                }
              } else {
                sendPerso(perso, cmd[3] + " est déjà active", true);
                break;
              }
            }
            let msg;
            if (er.activation) {
              if (!er.memeEffetQue || !attributeAsBool(perso, 'rune' + er.memeEffetQue))
                msg = er.activation.replace('%NOM', nomPerso(perso));
            }
            setTokenAttr(perso, 'rune' + cmd[3], true, evt, {
              msg
            });
            sendPerso(perso, er.description.replace('%SAGINT', caracSag), true);
            if (cmd[3] == 'Bryniza') {

              let token = perso.token;
              let pageId = token.get('pageid');
              let visionNoir = predicateAsInt(perso, 'visionDansLeNoir', 0);
              if (visionNoir <= 30) {
                let page = getObj('page', pageId);
                let udl = page && page.get('dynamic_lighting_enabled');
                if (udl) {
                  let vs = scaleDistance(perso, 50);
                  token.set('has_night_vision', true);
                  token.set('night_vision_effect', 'Dimming');
                  token.set('night_vision_distance', vs);
                  page.set('force_lighting_refresh', true);
                }
              }
            }
            break;
          }
        case 'desactiver':
          {
            let er = listeDesRunesMortes[cmd[3]];
            if (!er) {
              error("Rune " + cmd[3] + " non reconnue", cmd);
              break;
            }
            if (!attributeAsBool(perso, 'rune' + cmd[3])) {
              sendPerso(perso, cmd[3] + " n'est pas activée.", true);
              break;
            }
            let msg;
            if (er.fin) {
              if (!er.memeEffetQue || !attributeAsBool(perso, 'rune' + er.memeEffetQue))
                msg = er.fin.replace('%NOM', nomPerso(perso));
            }
            removeTokenAttr(perso, 'rune' + cmd[3], evt, {
              msg
            });
            if (cmd[3] == 'Bryniza') {

              let token = perso.token;
              let pageId = token.get('pageid');
              let visionNoir = predicateAsInt(perso, 'visionDansLeNoir', 0);
              if (visionNoir <= 30) {
                let page = getObj('page', pageId);
                let udl = page && page.get('dynamic_lighting_enabled');
                if (udl) {
                  if (visionNoir === 0) {
                    token.set('has_night_vision', false);
                  } else {
                    let vs = scaleDistance(perso, visionNoir);
                    token.set('night_vision_distance', vs);
                  }
                  page.set('force_lighting_refresh', true);
                }
              }
            }
            break;
          }
        case 'donner':
          {
            if (cmd.length < 4) {
              error("Il faut préciser le token à qui donner la rune", cmd);
              break;
            }
            let cible = persoOfId(cmd[4]);
            if (!cible) {
              error("Impossible de trouver à qui donner la rune", cmd);
              break;
            }
            let attr = tokenAttribute(perso, 'rune' + cmd[3]);
            if (attr.length > 0) {
              if (attr[0].get('current') == 'false') {
                let donne = attr[0].get('max');
                if (donne) {
                  sendPerso(perso, "a déjà donné " + cmd[3] + " à " + donne + ".", true);
                  break;
                }
              } else {
                sendPerso(perso, "Il faut d'abord désactiver " + cmd[3] + " avant de la donner", true);
                break;
              }
            }
            let er = listeDesRunesMortes[cmd[3]];
            if (!er) {
              error("Rune " + cmd[3] + " non reconnue", cmd);
              break;
            }
            let msg = nomPerso(perso) + " donne une rune à " + nomPerso(cible);
            let maxVal = nomPerso(cible);
            setTokenAttr(perso, 'rune' + cmd[3], 'false', evt, {
              msg,
              maxVal
            });
            sendPerso(perso, "peut maintenant communiquer par télépathie avec " + nomPerso(cible), true);
            sendPerso(cible, "peut maintenant communiquer par télépathie avec " + nomPerso(perso), true);
            break;
          }
        case 'recuperer':
          {
            let er = listeDesRunesMortes[cmd[3]];
            if (!er) {
              error("Rune " + cmd[3] + " non reconnue", cmd);
              break;
            }
            let attr = tokenAttribute(perso, 'rune' + cmd[3]);
            if (attr.length === 0) {
              sendPerso(perso, "a déjà " + cmd[3], true);
              break;
            }
            if (attr[0].get('current') != 'false') {
              sendPerso(perso, "a déjà " + cmd[3], true);
              break;
            }
            let donne = attr[0].get('max');
            if (!donne) {
              sendPerso(perso, "a déjà " + cmd[3], true);
              break;
            }
            let msg = nomPerso(perso) + " rappelle une rune sur le bâton";
            removeTokenAttr(perso, 'rune' + cmd[3], evt, {
              msg
            });
            sendPerso(perso, "ne peut plus communiquer par télépathie avec " + donne, true);
            break;
          }
        default:
          error("Action de gestion des runes " + cmd[2] + " non reconnue", cmd);
      }
    }
    let nombreDeRunes = 0;
    let etatDesRunes = [];
    for (let rune in listeDesRunesMortes) {
      let descr = listeDesRunesMortes[rune].description.replace('%SAGINT', caracSag);
      let er = {
        nom: rune,
        descr
      };
      let attr = tokenAttribute(perso, "rune" + rune);
      if (attr.length > 0) {
        let actif = attr[0].get('current') != 'false';
        if (actif) {
          nombreDeRunes++;
          er.actif = true;
        } else {
          let donne = attr[0].get('max');
          if (donne) er.donne = donne;
        }
      }
      etatDesRunes.push(er);
    }
    let maxActives = false;
    if (niveau < 2) maxActives = true;
    else maxActives = nombreDeRunes >= Math.ceil(niveau / 4);
    etatDesRunes.forEach(function (er) {
      let rune = er.nom;
      let ligne = 'title="' + er.descr + '"> ' + rune + '</span></strong> ';
      if (er.actif) {
        ligne = '<strong><span style="' + styleRuneActive + '" ' + ligne;
        let commande = '!cof-gerer-runes-mortes ' + cmd[1] + ' desactiver ' + rune;
        ligne += boutonSimple(commande, "désactiver");
      } else {
        ligne = '<strong><span ' + ligne;
        if (er.donne) {
          ligne += "donné à " + er.donne;
          let commande = '!cof-gerer-runes-mortes ' + cmd[1] + ' recuperer ' + rune;
          ligne += boutonSimple(commande, "récupérer");
        } else {
          if (!maxActives) {
            let commande = '!cof-gerer-runes-mortes ' + cmd[1] + ' activer ' + rune;
            ligne += boutonSimple(commande, "activer");
          }
          let commande = '!cof-gerer-runes-mortes ' + cmd[1] + ' donner ' + rune + ' @{target|token_id}';
          ligne += boutonSimple(commande, "donner");
        }
      }
      addLineToFramedDisplay(display, ligne);
    });
    sendFramedDisplay(display);
  }

  function immuniteDuGuerisseur(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    if (cmd.length < 2) {
      error("Il manque un argument à !cof-immunite-guerisseur", cmd);
      return;
    }
    let duree = parseInt(cmd[1]);
    if (isNaN(duree) || duree <= 0) {
      error("L'immunité a une durée incorrecte", cmd);
      return;
    }
    let pageId = options.pageId;
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Utilisation de !cof-immunite-guerisseur sans sélection de token", playerId);
        return;
      }
      const evt = {
        type: 'immunité du guérisseur'
      };
      addEvent(evt);
      if (options.lanceur &&
        limiteRessources(options.lanceur, options, 'immuniteDuGuerisseur', "lancer un sort d'immunité", evt)) return;
      initiative(selected, evt);
      let portee = 0;
      if (options.portee) portee = options.portee;
      iterSelected(selected, function (perso) {
        if (options.lanceur &&
          distanceCombat(options.lanceur.token, perso.token, pageId) > portee) {
          sendPlayer(msg, nomPerso(perso) + " est trop loin.", playerId);
          return;
        }
        let message = messageEffetTemp.immuniteAmaladie;
        let ef = {
          effet: 'immuniteAmaladie',
          duree: true,
          message,
          whisper: true,
        };
        setEffetTemporaire(perso, ef, duree, evt, options);
        ef.effet = 'immuniteApoison';
        ef.message = messageEffetTemp.immuniteApoison;
        setEffetTemporaire(perso, ef, duree, evt, options);
        sendPerso(perso, "est maintenant immunisé" + eForFemale(perso) + " au poison et aux maladies");
      });
    });
  }

  function lancerZoneDeVie(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    if (cmd.length < 2) {
      error("Il manque un argument à !cof-zone-de-vie", cmd);
      return;
    }
    let duree = parseInt(cmd[1]);
    if (isNaN(duree) || duree <= 0) {
      error("La zone de vie a une durée incorrecte", cmd);
      return;
    }
    let pageId = options.pageId;
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Utilisation de !cof-zone-de-vie sans sélection de token", playerId);
        return;
      }
      const evt = {
        type: 'zone de vie'
      };
      addEvent(evt);
      if (options.lanceur &&
        limiteRessources(options.lanceur, options, 'zoneDeVie', "lancer une zone de vie", evt)) return;
      initiative(selected, evt);
      iterSelected(selected, function (perso) {
        let n = 1;
        let attrName = 'zoneDeVie(' + n + ')';
        while (attributeAsBool(perso, attrName)) {
          n++;
          attrName = 'zoneDeVie(' + n + ')';
        }
        let scale = computeScale(pageId);
        let diametre = 20;
        if (options.portee) diametre = 2 * options.portee;
        diametre = diametre / scale;
        let diamPix = PIX_PER_UNIT * diametre;
        let imageFields = {
          _pageid: pageId,
          imgsrc: stateCOF.options.images.val.zone_de_vie.val,
          represents: '',
          left: perso.token.get('left'),
          top: perso.token.get('top'),
          width: diamPix,
          height: diamPix,
          layer: 'map',
          name: "Zone de vie " + n,
          isdrawing: true,
          emits_low_light: true,
          low_light_distance: diametre / 2,
        };
        let newImage = createObj('graphic', imageFields);
        if (newImage) {
          evt.tokens = evt.tokens || [];
          evt.tokens.push(newImage);
          toFront(newImage);
          setTokenAttr(perso, attrName + 'Id', newImage.id, evt);
          setAttrDuree(perso, attrName, duree, evt);
        } else {
          error("Impossible de créer l'image " + options.image, imageFields);
        }
      });
    }, options);
  }

  function cleanGlobalState(msg) {
    stateCOF = stateCOF || state.COFantasy;
    if (!stateCOF) {
      sendPlayer(msg, "État global de COF déjà vide");
      return;
    }
    try {
      removeRoundMarker();
    } catch (e) {
      stateCOF.roundMarkerId = undefined;
    }
    stateCOF.roundMarkerId = undefined;
    if (stateCOF.combat) {
      try {
        sortirDuCombat();
      } catch (e) {
        stateCOF.combat = undefined;
      }
    }
    stateCOF.combat = undefined;
    stateCOF.chargeFantastique = undefined;
    stateCOF.tokensTemps = undefined;
    stateCOF.effetAuD20 = undefined;
    stateCOF.tenebresMagiques = undefined;
    stateCOF.jetsEnCours = undefined;
    stateCOF.currentAttackDisplay = undefined;
    stateCOF.prescience = undefined;
    stateCOF.nextPrescience = undefined;
    stateCOF.afterDisplay = undefined;
    stateCOF.statistiquesEnPause = undefined;
    stateCOF.statistiques = undefined;
    stateCOF.personnageCibleCree = undefined;
    stateCOF.predicats = {};
    log("stateCOf purgé");
    log(stateCOF);
    sendPlayer(msg, "État global de COFantasy purgé.");
  }

  function poserBombe(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    if (cmd.length < 3) {
      error("Il manque des arguments pour !cof-poser-bombe", cmd);
      return;
    }
    let pageId = options.pageId;
    let arquebusier = persoOfId(cmd[1], cmd[1], pageId);
    if (!arquebusier) {
      error("Le premier argument de !cof-poser-bombe n'est pas un token valide", cmd);
      return;
    }
    pageId = pageId || arquebusier.token.get('pageid');
    let typeBombe;
    let portee;
    let message = "La bombe explose";
    let dm;
    let tempsDePose;
    let duree = 1;
    let intrusion;
    switch (cmd[2]) {
      case 'demolition':
      case 'démolition':
        {
          typeBombe = 'demolition';
          let rang = 2;
          if (cmd.length > 3) {
            rang = parseInt(cmd[3]);
            if (isNaN(rang))
              rang = predicateAsInt(arquebusier, cmd[3], 0, 2);
            if (rang < 1) {
              error("Rang de démolition " + cmd[3] + " incorrect", cmd);
              return;
            }
          } else rang = predicateAsInt(arquebusier, 'voieDesExplosifs', 2, 2);
          portee = 6;
          dm = rang + 'd6';
          let dmStruct = rollDePlus(6, {
            nbDes: 2 * rang
          });
          message += " et inflige " + dmStruct.roll + " DM à la structure (ignore la moitié de la RD)";
          tempsDePose = 3;
          break;
        }
      case 'piege':
      case 'piège':
        {
          typeBombe = 'piege';
          if (cmd.length < 5) {
            error("Il manque des arguments pour !cof-poser-bombe", cmd);
            return;
          }
          dm = cmd[3];
          portee = 3;
          switch (cmd[4]) {
            case 'retard':
            case 'retardé':
              tempsDePose = 1;
              if (cmd.length > 5) {
                duree = parseInt(cmd[5]);
                if (isNaN(duree) || duree < 1) {
                  error("Durée de retardement " + cmd[5] + " incorrecte");
                  return;
                }
              }
              break;
            case 'intrusion':
            case 'detection':
            case 'détection':
              tempsDePose = 2;
              intrusion = 1;
              duree = 100;
              if (cmd.length > 5) {
                intrusion = parseInt(cmd[5]);
                if (isNaN(intrusion) || intrusion < 1) {
                  error("Distance de détection " + cmd[5] + " incorrecte");
                  return;
                }
              }

              let scale = computeScale(pageId);
              intrusion = (intrusion / scale) * PIX_PER_UNIT;
              break;
            default:
              error("Type de piège explosif " + cmd[4] + " non reconnu", cmd);
              return;
          }
          break;
        }
      default:
        error("Type de bombe " + cmd[2] + " non reconnu", cmd);
        return;
    }
    let gmnotes = JSON.stringify({
      typeBombe,
      portee,
      message,
      dm,
      tempsDePose,
      duree,
      intrusion
    });
    let name = "Bombe " + generateUUID();
    const evt = {
      type: "Pose de bombe"
    };
    addEvent(evt);
    if (limiteRessources(arquebusier, options, 'poseBombe', "poser un explosif", evt)) return;

    let t = createObj('graphic', {
      _pageid: pageId,
      imgsrc: IMG_BOMB,
      represents: '',
      left: arquebusier.token.get('left'),
      top: arquebusier.token.get('top'),
      width: PIX_PER_UNIT,
      height: PIX_PER_UNIT * 0.8,
      layer: 'map',
      isDrawing: true,
      name,
      gmnotes
    });
    if (!t) {
      error("Impossible de créer le token de la bombe", IMG_BOMB);
      return;
    }
    toFront(t);
    evt.tokens = evt.tokens || [];
    evt.tokens.push(t);
    stateCOF.tokensTemps = stateCOF.tokensTemps || [];
    stateCOF.tokensTemps.push({
      tid: t.id,
      duree: duree + tempsDePose,
      name,
      init: getInit(),
      intrusion
    });

    let msgPose = "pose un explosif. ";
    if (tempsDePose < 2) msgPose += "Cela lui prend tout le tour";
    else {
      msgPose += onGenre(arquebusier, 'Il', 'Elle') + " y passe le tour et encore le";
      if (tempsDePose < 3) msgPose += " suivant.";
      else msgPose += "s " + (tempsDePose - 1) + " suivants.";
    }
    sendPerso(arquebusier, msgPose);
  }

  function mettreCasque(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    let label = -1;
    if (cmd.length > 1) label = toInt(cmd[1], -1);
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Personne pour mettre son casque", playerId);
        return;
      }
      const evt = {
        type: 'mettre casque'
      };
      addEvent(evt);
      iterSelected(selected, function (perso) {
        if (label === 0) {
          setFicheAttr(perso, 'teteequipe', '0', evt);
          sendPerso(perso, "enlève son casque", options.secret);
          purgeCachePredicats(perso);
          return;
        }
        let labelPerso = label;
        if (labelPerso == -1)
          labelPerso = toInt(ficheAttributeMax(perso, 'teteequipe', -1), -1);

        if (labelPerso > 0) {
          let armures = listAllArmors(perso);
          let casque = armures[labelPerso];
          if (!casque) {
            sendPlayer(msg, nomPerso(perso) + " n'a pas d'armure de label " + labelPerso, playerId);
            return;
          }
          if (casque.typearmure != 'Casque') {
            sendPlayer(msg, "L'armure de label " + labelPerso + " de " + nomPerso(perso) + " n'est pas un casque.", playerId);
            return;
          }
          sendPerso(perso, "met " + casque.nomarmure, options.secret);
        } else {
          sendPerso(perso, 'met son casque', options.secret);
          setFicheAttr(perso, 'casque_on', '1', evt);
        }
        purgeCachePredicats(perso);
        let opt = {};
        let current = ficheAttributeAsInt(perso, 'teteequipe', 0);
        if (current) opt.maxVal = current;
        setFicheAttr(perso, 'teteequipe', labelPerso, evt, opt);
      });
    });
  }

  function recupereMana(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    if (cmd.length < 2) {
      sendPlayer(msg, "Il manque le montant de mana à récupérer pour !cof-recupere-mana");
      return;
    }
    let mana = parseDice(cmd[1], "mana");
    if (mana === undefined) return;
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Personne ne récupère de mana", playerId);
        return;
      }
      const evt = {
        type: 'récupération de mana'
      };
      addEvent(evt);
      iterSelected(selected, function (perso) {
        let manaRes = manaInfo(perso);
        let manaAttr = manaRes.attribut ? [manaRes.attribut] : [];
        let manaMax = manaRes.max;
        if (!manaMax || manaMax < 0) {
          sendPerso(perso, "n'a pas de mana.");
          return;
        }
        let token = perso.token;
        let bar2 = parseInt(token.get('bar2_value'));
        if (isNaN(bar2)) {
          if (token.get('bar1_link') === '') bar2 = 0;
          else {
            sendPerso(perso, "*** Attention, la barre de mana du token n'est pas liée à la mana de la fiche ***");
            bar2 = parseInt(manaAttr[0].get('current'));
          }
        }
        if (bar2 >= manaMax) {
          sendPerso(perso, "est déjà au maximum de mana");
          return;
        }
        if (limiteRessources(perso, options, 'recupereMana', "récupérer de la mana", evt)) return;
        let r = rollDePlus(mana);
        let recupere = r.val;
        bar2 += recupere;
        if (bar2 >= manaMax) {
          recupere -= bar2 - manaMax;
          bar2 = manaMax;
        }
        let msg = "récupère ";
        if (r.val == recupere) msg += r.roll;
        else msg += recupere;
        msg += " PM";
        if (recupere > 1) msg += 's';
        if (r.val > recupere) msg += " (le résultat du jet était " + r.roll + ")";
        sendPerso(perso, msg, options.secret);
        updateCurrentBar(perso, 2, bar2, evt);
      });
    }, options);
  }

  function replaceTokenOfPerso(perso, token, evt, tokenFields) {
    if (token) {
      evt.tokens = evt.tokens || [];
      evt.tokens.push(token);
      let otherTokens;
      if (tokenFields) {
        let link = perso.token.get('bar1_link');
        if (link !== '') {
          otherTokens = findObjs({
            _type: 'graphic',
            _subtype: 'token',
            layer: 'objects',
            represents: perso.charId,
          });
          if (otherTokens.length < 3) {
            otherTokens = false;
          } else {
            let pageId = perso.token.get('pageid');
            otherTokens = otherTokens.filter(function (t) {
              return t.id !== perso.token.id && t.get('bar1_link') == link && t.get('pageid') != pageId;
            });
          }
        }
      }

      setToken(perso.token, 'layer', 'gmlayer', evt);
      setTokenAttr(perso, 'changementDeToken', true, evt);
      if (stateCOF.combat) replaceInTurnTracker(perso.token.id, token.id, evt);
      perso.token = token;
      if (!otherTokens) return;
      otherTokens.forEach(function (oldToken) {
        tokenFields._pageid = oldToken.get('pageid');
        tokenFields.left = oldToken.get('left');
        tokenFields.top = oldToken.get('top');
        tokenFields.rotation = oldToken.get('rotation');
        let newToken = createObj('graphic', tokenFields);
        if (newToken) {
          evt.tokens.push(newToken);
          setToken(oldToken, 'layer', 'gmlayer', evt);
        }
      });
    }
  }

  function restoreTokenOfPerso(perso, evt) {
    let tokenChange = attributeAsBool(perso, 'changementDeToken');
    if (!tokenChange) return;
    removeTokenAttr(perso, 'changementDeToken', evt);
    let res;
    let token = perso.token;

    let otherTokens;
    let link = perso.token.get('bar1_link');
    if (link !== '') {
      otherTokens = findObjs({
        _type: 'graphic',
        _subtype: 'token',
        layer: 'objects',
        represents: perso.charId,
      });
      if (otherTokens.length < 2) {
        otherTokens = false;
      } else {
        otherTokens = otherTokens.filter(function (t) {
          return t.id !== token.id && t.get('bar1_link') == link;
        });
      }
    }
    let tokenMJ =
      findObjs({
        _type: 'graphic',
        _subtype: 'token',
        _pageid: token.get('pageid'),
        layer: 'gmlayer',
        represents: perso.charId,
        name: token.get('name')
      });
    if (tokenMJ.length === 0) {
      tokenMJ =
        findObjs({
          _type: 'graphic',
          _subtype: 'token',
          layer: 'gmlayer',
          represents: perso.charId,
          name: token.get('name')
        });
    }
    if (tokenMJ.length === 0) {
      let character = getObj('character', perso.charId);
      character.get('_defaulttoken', function (defToken) {
        defToken = cofParseDefaultToken(defToken);
        if (defToken) {
          defToken.imgsrc = thumbImage(defToken.imgsrc);
          defToken.layer = 'objects';
          defToken.left = token.get('left');
          defToken.top = token.get('top');
          defToken.pageid = token.get('pageid');
          let newToken = createObj('graphic', defToken);
          if (newToken) {
            res = copyOldTokenToNewToken(newToken, perso, evt);
            return;
          }
        }
        error("Impossible de retrouver le token d'origine du personnage", perso);
      });
      return;
    }
    res = copyOldTokenToNewToken(tokenMJ[0], perso, evt);
    if (!otherTokens) return;
    otherTokens.forEach(function (token) {
      let tokenMJ =
        findObjs({
          _type: 'graphic',
          _subtype: 'token',
          _pageid: token.get('pageid'),
          layer: 'gmlayer',
          represents: perso.charId,
          name: token.get('name')
        });
      if (tokenMJ.length === 0) return;
      let otherPerso = {
        token,
        charId: perso.charId
      };
      copyOldTokenToNewToken(tokenMJ[0], otherPerso, evt);
    });
    return res;
  }

  function copyOldTokenToNewToken(nouveauToken, perso, evt) {
    let token = perso.token;
    setToken(nouveauToken, 'layer', 'objects', evt);
    setToken(nouveauToken, 'left', token.get('left'), evt);
    setToken(nouveauToken, 'top', token.get('top'), evt);

    setToken(nouveauToken, 'rotation', token.get('rotation'), evt);
    setToken(nouveauToken, 'bar2_value', token.get('bar2_value'), evt);
    setToken(nouveauToken, 'aura1_radius', token.get('aura1_radius'), evt);
    setToken(nouveauToken, 'aura1_color', token.get('aura1_color'), evt);
    setToken(nouveauToken, 'aura1_square', token.get('aura1_square'), evt);
    setToken(nouveauToken, 'showplayers_aura1', token.get('showplayers_aura1'), evt);
    setToken(nouveauToken, 'aura2_radius', token.get('aura2_radius'), evt);
    setToken(nouveauToken, 'aura2_color', token.get('aura2_color'), evt);
    setToken(nouveauToken, 'aura2_square', token.get('aura2_square'), evt);
    setToken(nouveauToken, 'showplayers_aura2', token.get('showplayers_aura2'), evt);
    setToken(nouveauToken, 'statusmarkers', token.get('statusmarkers'), evt);
    setToken(nouveauToken, 'light_angle', token.get('light_angle'), evt);
    setToken(nouveauToken, 'has_limit_field_of_vision', token.get('has_limit_field_of_vision'), evt);
    setToken(nouveauToken, 'has_limit_field_of_night_vision', token.get('has_limit_field_of_night_vision'), evt);
    if (stateCOF.combat) {
      replaceInTurnTracker(token.id, nouveauToken.id, evt);
    }
    let res = {
      oldTokenId: token.id,
      newTokenId: nouveauToken.id,
      newToken: nouveauToken,
    };
    deleteTokenWithUndo(token, evt);
    perso.token = nouveauToken;
    return res;
  }

  let regFicheAttr = /^[a-zA-Z0-9]+$/;

  function changerDeForme(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    if (cmd.length < 2) {
      sendPlayer(msg, "Il manque le nom de la forme pour !cof-changer-de-forme");
      return;
    }
    let nomForme = cmd.slice(1).join(' ');
    let formeChar = findObjs({
      _type: 'character',
      name: nomForme
    });
    if (formeChar.length === 0) {
      error("Impossible trouver de fiche pour \"" + nomForme + "\"", cmd);
      return;
    }
    if (formeChar.length > 1) {
      sendPlayer(msg, "Il existe plus d'une fiche pour " + nomForme);
    }
    formeChar = formeChar[0];
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Utilisation de !cof-changer-de-forme sans sélection de token", playerId);
        return;
      }
      const evt = {
        type: 'changement de forme'
      };
      addEvent(evt);
      if (options.lanceur &&
        limiteRessources(options.lanceur, options, 'changementDeForme', "changer de forme", evt)) return;
      formeChar.get('_defaulttoken', function (token) {
        token = cofParseDefaultToken(token);
        iterSelected(selected, function (perso) {
          if (attributeAsBool(perso, 'changementDeForme')) {
            sendPerso(perso, "est déjà transformé");
            return;
          }
          if (token) {
            let tokenFields = getTokenFields(perso.token);
            tokenFields.imgsrc = thumbImage(token.imgsrc);
            tokenFields.width = token.width;
            tokenFields.height = token.height;
            if (attributeAsBool(perso, 'agrandissement')) {
              tokenFields.width += token.width / 2;
              tokenFields.height += token.height / 2;
            }
            let newToken = createObj('graphic', tokenFields);
            replaceTokenOfPerso(perso, newToken, evt, tokenFields);
            perso.toutesLesAttaques = undefined;
          } else {
            sendChat('', "/w GM L'image du token de " + nomPerso(perso) + " n'est pas utilisable par le script. Utiliser une image de votre librairie.");
          }
          sendPerso(perso, "se transforme en " + nomForme, options.secret);
          let optSet = {};
          if (options.gardeCarac) {
            let garde = '';
            options.gardeCarac.forEach(function (c) {
              c = c.trim();
              if (regFicheAttr.test(c)) garde += c.toLowerCase() + ',';
            });
            if (garde) optSet.maxVal = garde.substring(0, garde.length - 1);
          }
          if (options.gardeCaracSiMeilleure) {
            let garde = '';
            options.gardeCaracSiMeilleure.forEach(function (c) {
              c = c.trim();
              if (regFicheAttr.test(c)) garde += c.toLowerCase() + ',';
            });
            if (garde) {
              garde = '||' + garde.substring(0, garde.length - 1);
              if (optSet.maxVal) garde = optSet.maxVal + garde;
              optSet.maxVal = garde;
            }
          }
          setTokenAttr(perso, 'changementDeForme', nomForme, evt, optSet);
          if (predicateAsBool(perso, 'transformationRegeneratrice')) {
            setTokenAttr(perso, 'PVAvantTransformation', perso.token.get('bar1_value'), evt);
          }
          if (options.utiliserAttaqueMagique) {
            setTokenAttr(perso, 'changementDeFormeUtiliseAttaqueMag', true, evt);
          }
          if (options.augmentePVs) {
            let pv = ficheAttributeMax({
              charId: formeChar.id
            }, 'pv', 0);
            if (pv > 0) {
              setTokenAttr(perso, 'PVTempChangementDeForme', Math.ceil(pv / 5), evt);
            }
          }
          stateCOF.predicats[perso.charId] = undefined;
        });
      });
    }, options);
  }

  function finChangementDeForme(msg) {
    let options = parseOptions(msg);
    if (options === undefined) return;
    let cmd = options.cmd;
    if (cmd === undefined) {
      error("Problème de parse options", msg.content);
      return;
    }
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Utilisation de !cof-fin-changement-de-forme sans sélection de token", playerId);
        return;
      }
      const evt = {
        type: 'fin de changement de forme'
      };
      addEvent(evt);
      if (options.lanceur &&
        limiteRessources(options.lanceur, options, 'finChangementDeForme', "retrouver sa forme normale", evt)) return;
      iterSelected(selected, function (perso) {
        if (!attributeAsBool(perso, 'changementDeForme')) {
          sendPerso(perso, "a déjà sa forme normale.", options.secret);
        }
        restoreTokenOfPerso(perso, evt);
        sendPerso(perso, "retrouve sa forme normale", options.secret);
        if (options.transformationRegeneratrice) {
          let anciensPVs = attributeAsInt(perso, 'PVAvantTransformation', -1);
          if (anciensPVs < 0) {
            error("Impossible de trouver les PVs du moment de la transformation", anciensPVs);
          } else {
            let pv = parseInt(perso.token.get('bar1_value'));
            if (!isNaN(pv) && anciensPVs > pv) {
              let jetSoins = rollDePlus({
                dice: 6,
                nbDe: 3
              });
              let msg = " la transformation " + onGenre(perso, 'le', 'la') + " soigne de ";
              let soins = jetSoins.val;
              if (pv + soins > anciensPVs) {
                soins = anciensPVs - pv;
                msg += soins + " PV (le jet était " + jetSoins.roll + ")";
              } else {
                msg += jetSoins.roll + " PVs";
              }
              sendPerso(perso, msg);
              soigneToken(perso, soins, evt);
            }
          }
        }
        removeTokenAttr(perso, 'changementDeForme', evt);
        removeTokenAttr(perso, 'PVAvantTransformation', evt);
        removeTokenAttr(perso, 'changementDeFormeUtiliseAttaqueMag', evt);
        removeTokenAttr(perso, 'PVTempChangementDeForme', evt);
        stateCOF.predicats[perso.charId] = undefined;
      });
    }, options);
  }

  function divisionVase(msg) {
    getSelected(msg, function (selected, playerId) {
      if (selected.length === 0) {
        sendPlayer(msg, "Pas de vase à diviser", playerId);
        return;
      }
      const evt = {
        type: 'division de vase'
      };
      addEvent(evt);
      iterSelected(selected, function (perso) {
        let pv = parseInt(perso.token.get('bar1_value'));
        if (isNaN(pv) || pv < 11) {
          sendPlayer(msg, "Pas assez de PV (" + pv + ") pour se diviser", playerId);
          return;
        }
        let pv_max = parseInt(perso.token.get('bar1_max'));
        if (isNaN(pv_max) || pv_max < pv) pv_max = pv;
        pv = Math.floor(pv / 2);
        pv_max = Math.floor(pv_max / 2);
        updateCurrentBar(perso, 1, pv, evt, pv_max);

        let width = perso.token.get('width');
        let height = perso.token.get('height');
        width = Math.ceil(width * 0.9);
        height = Math.ceil(height * 0.9);
        setToken(perso.token, 'width', width, evt);
        setToken(perso.token, 'height', height, evt);
        let tokenFields = getTokenFields(perso.token);
        tokenFields.imgsrc = thumbImage(tokenFields.imgsrc);
        let token2 = createObj('graphic', tokenFields);
        if (!token2) {
          sendPlayer(msg, "Pas moyen de copier, le faire à la main", playerId);
        } else {
          sendPlayer(msg, "token créé. Le bouger et le renommer", playerId);
        }
        sendPerso(perso, "se divise en deux");
      });
    });
  }

  function doctorHtml(s) {
    return String(s === undefined || s === null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function doctorAllAttributes(cid) {
    return findObjs({_type:'attribute', _characterid:cid}) || [];
  }

  function doctorAttrsCI(cid, name) {
    let low = String(name).toLowerCase();
    return doctorAllAttributes(cid).filter(function(a) {
      return String(a.get('name') || '').toLowerCase() === low;
    });
  }

  function doctorSameValue(a, b) {
    return String(a.get('current') === undefined ? '' : a.get('current')) === String(b.get('current') === undefined ? '' : b.get('current')) &&
      String(a.get('max') === undefined ? '' : a.get('max')) === String(b.get('max') === undefined ? '' : b.get('max'));
  }

  function doctorRelinkLiveTokens(cid, oldId, newId) {
    let n = 0;
    if (!oldId || !newId || oldId === newId) return n;
    (findObjs({_type:'graphic', _subtype:'token', represents:cid}) || []).forEach(function(t) {
      ['bar1_link','bar2_link','bar3_link'].forEach(function(field) {
        if (t.get(field) === oldId) { t.set(field, newId); n++; }
      });
    });
    return n;
  }

  function doctorCanonicalAttribute(cid, name, result) {
    let attrs = doctorAttrsCI(cid, name);
    if (!attrs.length) return undefined;
    let exact = attrs.filter(function(a){return a.get('name') === name;});
    let canonical = exact[0] || attrs[0];
    if (attrs.length > 1) {
      result.issues.push(name + ' possède ' + attrs.length + ' attributs concurrents');
      attrs.forEach(function(a) {
        if (a.id === canonical.id) return;
        if (doctorSameValue(a, canonical)) {
          result.relinks[a.id] = canonical.id;
          if (result.repair) {
            let nr = doctorRelinkLiveTokens(cid, a.id, canonical.id);
            a.remove();
            result.fixes.push('doublon ' + name + ' identique supprimé' + (nr ? ' (' + nr + ' lien(s) corrigé(s))' : ''));
          }
        } else {
          result.unresolved.push(name + ' : doublons avec valeurs différentes (' + a.get('current') + '/' + a.get('max') + ' vs ' + canonical.get('current') + '/' + canonical.get('max') + ')');
        }
      });
    }
    if (canonical.get('name') !== name) {
      result.issues.push(name + ' utilise encore le nom historique « ' + canonical.get('name') + ' »');
      if (result.repair && attrs.length === 1) {
        let replacement = createObj('attribute',{characterid:cid,name:name,current:canonical.get('current'),max:canonical.get('max')});
        if (replacement) {
          result.relinks[canonical.id] = replacement.id;
          let nr = doctorRelinkLiveTokens(cid, canonical.id, replacement.id);
          canonical.remove(); canonical = replacement;
          result.fixes.push(name + ' renommé vers le nom canonique' + (nr ? ' (' + nr + ' lien(s) corrigé(s))' : ''));
        }
      }
    }
    return canonical;
  }

  function doctorMigrateLegacyField(cid, legacyName, canonicalName, result, numeric) {
    let legacy = (findObjs({_type:'attribute',_characterid:cid,name:legacyName}) || [])[0];
    if (!legacy) return;
    let canonical = (findObjs({_type:'attribute',_characterid:cid,name:canonicalName}) || [])[0];
    result.issues.push(legacyName + ' est un ancien attribut remplacé par ' + canonicalName);
    if (!result.repair) {
      if (canonical) result.relinks[legacy.id] = canonical.id;
      return;
    }
    if (!canonical) {
      canonical = createObj('attribute',{characterid:cid,name:canonicalName,current:legacy.get('current'),max:legacy.get('max')});
      if (!canonical) return;
      result.fixes.push(canonicalName + ' créé depuis ' + legacyName);
    } else if (!doctorSameValue(legacy, canonical)) {
      let liveLinked = (findObjs({_type:'graphic',_subtype:'token',represents:cid}) || []).some(function(t){return t.get('bar1_link')===legacy.id||t.get('bar2_link')===legacy.id||t.get('bar3_link')===legacy.id;});
      let canCur = String(canonical.get('current') || ''), canMax = String(canonical.get('max') || '');
      let canonicalEmpty = numeric ? ((parseInt(canCur)||0)===0 && (parseInt(canMax)||0)===0) : (canCur.trim()==='');
      if (liveLinked || canonicalEmpty) {
        canonical.set('current',legacy.get('current')); canonical.set('max',legacy.get('max'));
        result.fixes.push(canonicalName + ' synchronisé depuis l’ancien ' + legacyName);
      } else {
        result.unresolved.push(legacyName + ' et ' + canonicalName + ' ont des valeurs différentes');
        return;
      }
    }
    result.relinks[legacy.id] = canonical.id;
    doctorRelinkLiveTokens(cid, legacy.id, canonical.id);
    legacy.remove();
    result.fixes.push(legacyName + ' supprimé après migration');
  }

  function doctorValidateNumericResource(cid, name, result, defaults) {
    let a = doctorCanonicalAttribute(cid, name, result); if (!a) return;
    let cur = parseInt(a.get('current')), mx = parseInt(a.get('max'));
    if (isNaN(cur) || cur < 0) {
      result.issues.push(name + '.current invalide : ' + a.get('current'));
      if (result.repair) { a.set('current', 0); cur = 0; result.fixes.push(name + '.current remis à 0'); }
    }
    if (isNaN(mx) || mx < 0) {
      result.issues.push(name + '.max invalide : ' + a.get('max'));
      if (result.repair && defaults !== undefined) { mx = defaults; a.set('max', mx); result.fixes.push(name + '.max remis à ' + mx); }
    }
    if (!isNaN(cur) && !isNaN(mx) && cur > mx) {
      result.issues.push(name + ' courant (' + cur + ') supérieur au maximum (' + mx + ')');
      if (result.repair) { a.set('current', mx); result.fixes.push(name + ' courant ramené au maximum'); }
    }

    (findObjs({_type:'attribute',_characterid:cid,name:name+'_max'}) || []).forEach(function(shadow) {
      result.issues.push('attribut fantôme ' + name + '_max');
      if (result.repair) {
        let sv=parseInt(shadow.get('current')), cm=parseInt(a.get('max'));
        if ((isNaN(cm)||cm<=0) && !isNaN(sv) && sv>=0) { a.set('max',sv); result.fixes.push('maximum de '+name+' restauré à '+sv); }
        shadow.remove(); result.fixes.push(name + '_max supprimé');
      }
    });
  }

  function doctorBumpCounter(cid, counter, regex, result, repairDuplicates) {
    let maxSeen=0, labels={}, used={};
    doctorAllAttributes(cid).forEach(function(a) {
      let m=regex.exec(String(a.get('name')||'')); if(!m)return;
      let v=parseInt(a.get('current')); if(isNaN(v)||v<1)return;
      maxSeen=Math.max(maxSeen,v);
      used[v]=true;
      if(!labels[v])labels[v]=[];
      labels[v].push(a);
    });
    Object.keys(labels).forEach(function(k){
      let group=labels[k];
      if(group.length<=1)return;
      if(result.repair&&repairDuplicates){

        group.sort(function(a,b){return String(a.get('name')||'').localeCompare(String(b.get('name')||''));});
        for(let i=1;i<group.length;i++){
          do { maxSeen++; } while(used[maxSeen]);
          used[maxSeen]=true;
          group[i].set('current',maxSeen);
          result.fixes.push(counter+' : doublon '+k+' renuméroté en '+maxSeen);
        }
      } else {
        result.unresolved.push(counter+' : label '+k+' utilisé '+group.length+' fois');
      }
    });
    let ca=exactCharAttribute(cid,counter), cv=ca?parseInt(ca.get('current')):0;if(isNaN(cv))cv=0;
    if(maxSeen>cv){
      result.issues.push(counter+'='+cv+' inférieur au plus grand label '+maxSeen);
      if(result.repair){
        if(ca)ca.set('current',maxSeen);
        else createObj('attribute',{characterid:cid,name:counter,current:maxSeen});
        result.fixes.push(counter+' remonté à '+maxSeen);
      }
    }
  }

  function doctorTriggerSheetMigration(cid, result) {
    let v=exactCharAttribute(cid,'version'), parsed=v?parseFloat(v.get('current')):0;
    if (!v || isNaN(parsed) || parsed < versionFiche) {
      result.issues.push('fiche ' + (v ? v.get('current') : 'sans version') + ' à migrer vers ' + versionFiche);
      if (result.repair) {
        let tick=exactCharAttribute(cid,'cof_doctor_tick');
        if(!tick)tick=createObj('attribute',{characterid:cid,name:'cof_doctor_tick',current:'0'});
        if(tick&&tick.setWithWorker)tick.setWithWorker({current:String(Date.now())});
        else if(tick)tick.set('current',String(Date.now()));
        result.fixes.push('migrations officielles de la fiche déclenchées');
      }
    } else if (parsed > versionFiche) result.unresolved.push('version de fiche plus récente ('+parsed+') que le script ('+versionFiche+')');
  }

  function doctorCoreCharacter(character, repair) {
    let cid=character.id, result={repair:repair,issues:[],fixes:[],unresolved:[],relinks:{}};
    let tp=exactCharAttribute(cid,'type_personnage'), type=tp?String(tp.get('current')||'').toUpperCase():'';

    if (!['OBJET','CONSOMMABLE','HEBERGEMENT'].includes(type)) doctorTriggerSheetMigration(cid,result);

    doctorMigrateLegacyField(cid,'pnj_pv','PV',result,true);
    doctorMigrateLegacyField(cid,'pnj_dmtemp','DMTEMP',result,true);
    doctorMigrateLegacyField(cid,'pnj_rd','RDS',result,false);
    if(type==='PJ'||type==='PNJ'||exactCharAttribute(cid,'PV'))doctorValidateNumericResource(cid,'PV',result,0);
    if(type==='PJ'){
      let op=exactCharAttribute(cid,'option_pr'),oc=exactCharAttribute(cid,'option_pc');
      let prOn=!op||!['0','false'].includes(String(op.get('current')||'').toLowerCase()), pcOn=!oc||!['0','false'].includes(String(oc.get('current')||'').toLowerCase());
      if(prOn&&!doctorAttrsCI(cid,'pr').length){result.issues.push('pr absent');if(repair){createObj('attribute',{characterid:cid,name:'pr',current:3,max:3});result.fixes.push('pr créé à 3/3');}}
      if(pcOn&&!doctorAttrsCI(cid,'pc').length){result.issues.push('pc absent');if(repair){createObj('attribute',{characterid:cid,name:'pc',current:3,max:3});result.fixes.push('pc créé à 3/3');}}
      if(prOn)doctorValidateNumericResource(cid,'pr',result,3);if(pcOn)doctorValidateNumericResource(cid,'pc',result,3);
    }
    if(doctorAttrsCI(cid,'pm').length)doctorValidateNumericResource(cid,'pm',result,0);

    let pr=exactCharAttribute(cid,'pr'), olds=[];['PR1','PR2','PR3','PR4','PR5'].forEach(function(n){(findObjs({_type:'attribute',_characterid:cid,name:n})||[]).forEach(function(a){olds.push(a);});});
    if(olds.length){result.issues.push(olds.length+' ancien(s) compteur(s) PR1–PR5');if(repair&&pr){olds.forEach(function(a){a.remove();});result.fixes.push('anciens compteurs PR1–PR5 supprimés');}}

    doctorBumpCounter(cid,'max_attack_label',/^repeating_(?:armes|pnjatk)_[^_]+_armelabel$/,result,true);
    doctorBumpCounter(cid,'max_armure_label',/^repeating_armures_[^_]+_labelarmure$/,result,false);
    doctorBumpCounter(cid,'max_munition_label',/^repeating_munitions_[^_]+_labelmunition$/,result,false);
    ['','1','2','3','4'].forEach(function(suf){let sec='actions'+suf,c='maxrangaction'+suf;doctorBumpCounter(cid,c,new RegExp('^repeating_'+sec+'_[^_]+_actionrang$'),result,false);});

    let pv=exactCharAttribute(cid,'PV'),pm=exactCharAttribute(cid,'pm');
    (findObjs({_type:'graphic',_subtype:'token',represents:cid})||[]).forEach(function(t){
      [['bar1_link',pv,'PV'],['bar2_link',pm,'pm']].forEach(function(spec){let link=t.get(spec[0]);if(!link||!spec[1])return;let a=getObj('attribute',link);if(a&&String(a.get('name')||'').toLowerCase()===spec[2].toLowerCase()&&a.id!==spec[1].id){result.issues.push((t.get('name')||'token')+' : '+spec[0]+' sur ancien '+spec[2]);result.relinks[a.id]=spec[1].id;if(repair){t.set(spec[0],spec[1].id);result.fixes.push((t.get('name')||'token')+' : '+spec[0]+' reliée à '+spec[2]);}}});
    });

    if(typeof COFantasyItems!=='undefined'&&COFantasyItems&&typeof COFantasyItems.doctorCharacter==='function'){
      try{let cr=COFantasyItems.doctorCharacter(character,repair)||{};(cr.issues||[]).forEach(function(x){result.issues.push('Objets : '+x);});(cr.fixes||[]).forEach(function(x){result.fixes.push('Objets : '+x);});(cr.unresolved||[]).forEach(function(x){result.unresolved.push('Objets : '+x);});}catch(e){result.unresolved.push('COFantasy Items Doctor : '+e.message);}
    }
    return result;
  }

  function doctorDefaultToken(character, result, callback) {
    if(!character||typeof character.get!=='function'){callback();return;}
    character.get('_defaulttoken',function(raw){
      if(!raw){callback();return;}
      let data;try{data=JSON.parse(raw);}catch(e){result.unresolved.push('token par défaut illisible : '+e.message);callback();return;}

      if(!data||typeof data!=='object'||Array.isArray(data)){callback();return;}
      let changed=false;
      ['bar1_link','bar2_link','bar3_link'].forEach(function(f){
        let link=data[f];if(!link)return;
        if(result.relinks[link]){result.issues.push('token par défaut : '+f+' pointe vers un ancien attribut');if(result.repair){data[f]=result.relinks[link];changed=true;}}
        else if(!getObj('attribute',link))result.unresolved.push('token par défaut : '+f+' pointe vers un attribut inexistant');
      });
      if(changed&&typeof setDefaultTokenForCharacter==='function'){
        try{
          data.represents=character.id;
          let tok=createObj('graphic',data);
          if(tok){setDefaultTokenForCharacter(character,tok);tok.remove();result.fixes.push('liens du token par défaut réparés');}
          else result.unresolved.push('impossible de recréer le token par défaut pour corriger ses liens');
        }catch(e){result.unresolved.push('réparation du token par défaut impossible : '+e.message);}
      }
      callback();
    });
  }

  function doctorCharacterCard(ch,r){
    if(!r.issues.length&&!r.fixes.length&&!r.unresolved.length)return '';
    let x='<div style="border-top:1px solid #d8c8a8;margin-top:5px;padding-top:4px"><b>'+doctorHtml(ch.get('name'))+'</b>';
    r.issues.forEach(function(v){x+='<div style="font-size:10px;color:#8a5a32">⚠ '+doctorHtml(v)+'</div>';});
    r.fixes.forEach(function(v){x+='<div style="font-size:10px;color:#3f6b45">✓ '+doctorHtml(v)+'</div>';});
    r.unresolved.forEach(function(v){x+='<div style="font-size:10px;color:#9b2e22">✖ '+doctorHtml(v)+'</div>';});
    return x+'</div>';
  }

  function doctorSendChunks(cards,summary,repair,totalIssues){
    let head='<div style="background:#fffaf2;border:1px solid #6f4a26;padding:8px;border-radius:6px"><div style="font-weight:bold;font-size:15px;text-align:center">🩺 COFantasy Doctor'+(repair?' — réparation':'')+'</div>';
    let chunks=[],cur=head;
    cards.forEach(function(card){if(cur.length+card.length>6500){chunks.push(cur+'</div>');cur=head;}cur+=card;});
    cur+='<hr>'+summary;
    if(!repair&&totalIssues)cur+='<div style="margin-top:5px">'+boutonSimple('!cof-doctor --repair','Réparer les anomalies sûres')+'</div>';
    if(repair)cur+='<div style="margin-top:5px">'+boutonSimple('!cof-doctor','Recontrôler après migrations')+'</div>';
    cur+='</div>';chunks.push(cur);
    chunks.forEach(function(c){sendChat('COF','/w gm '+c,null,{noarchive:true});});
  }

  function cofDoctor(msg) {
    let playerId=getPlayerIdFromMsg(msg);
    if(!playerId||!playerIsGM(playerId)){sendPlayer(msg,'Seul le MJ peut lancer !cof-doctor.');return;}
    let repair=/(?:^|\s)--repair(?:\s|$)/i.test(msg.content),chars=[],seen={};

    if(msg.selected&&msg.selected.length)msg.selected.forEach(function(sel){
      let tok=getObj('graphic',sel._id),cid=tok&&tok.get('represents'),ch=cid&&getObj('character',cid);
      if(ch&&!seen[cid]){seen[cid]=true;chars.push(ch);}
    });

    if(!chars.length)(findObjs({_type:'character'})||[]).forEach(function(ch){
      let cid=ch.id,tp=exactCharAttribute(cid,'type_personnage'),
          type=tp?String(tp.get('current')||'').toUpperCase():'',
          v=exactCharAttribute(cid,'version'),sv=exactCharAttribute(cid,'scriptVersion'),
          oc=exactCharAttribute(cid,'objet_categorie'),dv=exactCharAttribute(cid,'DV');
      if(['PJ','PNJ','OBJET','CONSOMMABLE','HEBERGEMENT'].includes(type)||v||sv||oc||(dv&&parseInt(dv.get('current'))>0))chars.push(ch);
    });

    if(!chars.length){doctorSendChunks([], '<b>0</b> fiche COFantasy détectée.', repair, 0);return;}

    function runPass(doRepair, done) {
      let results=[],pending=chars.length;
      chars.forEach(function(ch){
        let r=doctorCoreCharacter(ch,doRepair);
        results.push({ch:ch,r:r});
        doctorDefaultToken(ch,r,function(){
          pending--;
          if(pending===0)done(results);
        });
      });
    }

    function render(results, repairFixes) {
      let cards=[],ti=0,tf=0,tu=0,fixById={};
      (repairFixes||[]).forEach(function(e){fixById[e.ch.id]=(e.r.fixes||[]).slice();});
      results.forEach(function(e){
        let fixes=fixById[e.ch.id]||e.r.fixes||[];
        let shown={issues:e.r.issues||[],fixes:fixes,unresolved:e.r.unresolved||[]};
        ti+=shown.issues.length;tf+=shown.fixes.length;tu+=shown.unresolved.length;
        let c=doctorCharacterCard(e.ch,shown);if(c)cards.push(c);
      });
      let summary='<b>'+chars.length+'</b> fiche(s) · <b>'+ti+'</b> anomalie(s) restante(s)'
        +(repair?' · <b>'+tf+'</b> correction(s) appliquée(s)':'')
        +(tu?' · <b>'+tu+'</b> à vérifier manuellement':'')+'.';
      doctorSendChunks(cards,summary,repair,ti);
    }

    if(!repair){
      runPass(false,function(results){render(results,null);});
      return;
    }

    runPass(true,function(repairResults){

      setTimeout(function(){
        runPass(false,function(afterResults){render(afterResults,repairResults);});
      },250);
    });
  }

  let cofMouvementsProgrammes = {};

  function cofEscapeHtml(txt) {
    return String(txt === undefined ? '' : txt)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  function cofMissionCard(titre, contenu, couleur) {
    couleur = couleur || '#694b2b';
    return '<div style="border:1px solid ' + couleur + ';background:#f8f3e8;border-radius:6px;overflow:hidden;font-family:Arial,sans-serif">' +
      '<div style="background:' + couleur + ';color:white;font-weight:bold;padding:6px 8px;text-align:center">' + titre + '</div>' +
      '<div style="padding:7px 8px;color:#251d15">' + contenu + '</div></div>';
  }

  function cofWhisperPlayer(playerId, html) {
    if (!playerId) {
      sendChat('COF', '/w GM ' + html);
      return;
    }
    let pl = getObj('player', playerId);
    if (!pl) {
      sendChat('COF', '/w GM ' + html);
      return;
    }
    let n = String(pl.get('_displayname') || pl.get('displayname') || '').replace(/"/g, '');
    sendChat('COF', '/w "' + n + '" ' + html);
  }

  function cofPlayerIdsControleur(perso) {
    if (!perso) return [];
    let character = getObj('character', perso.charId);
    if (!character) return [];
    let raw = String(character.get('controlledby') || '');
    if (!raw) return [];
    let ids = raw.split(',').map(function(x){ return x.trim(); }).filter(Boolean);
    let all = ids.indexOf('all') >= 0;
    let res = [];
    if (all) {
      (findObjs({_type:'player'}) || []).forEach(function(pl) {
        if (!pl) return;
        let pid = pl.id;
        if (playerIsGM(pid)) return;
        let online = pl.get('online');
        if (online === undefined) online = pl.get('_online');
        if (online && res.indexOf(pid) < 0) res.push(pid);
      });
    }
    ids.forEach(function(pid) {
      if (pid == 'all') return;
      let pl = getObj('player', pid);
      if (!pl) return;
      let online = pl.get('online');
      if (online === undefined) online = pl.get('_online');
      if (online && res.indexOf(pid) < 0) res.push(pid);
    });
    return res;
  }

  function cofMissionOptions(content) {
    let parts = String(content || '').split(' --');
    let first = parts.shift().trim().split(/\s+/);
    let res = { cmd:first };
    parts.forEach(function(part) {
      part = part.trim();
      if (!part) return;
      let sp = part.split(/\s+/);
      let key = sp.shift();
      res[key] = sp.join(' ').trim();
      if (res[key] === '') res[key] = true;
    });
    return res;
  }

  function cofSelectedTokenIds(msg) {
    if (!msg || !msg.selected) return [];
    return msg.selected.map(function(s) { return s._id; }).filter(function(id) {
      return !!getObj('graphic', id);
    });
  }

  function cofPersoAllie(a, b) {
    if (!a || !b) return false;
    if (a.charId == b.charId) return true;
    let aa = alliesParPerso[a.charId];
    let ab = alliesParPerso[b.charId];
    if (aa && aa.has(b.charId)) return true;
    if (ab && ab.has(a.charId)) return true;

    if (estAllieJoueur(a) && estAllieJoueur(b)) return true;
    return false;
  }

