  function cofMissionDraftNouveau(type, pageId, callback) {
    cofMissionDrafts();
    cofMissionParticipantsPrincipaux(pageId, function(principaux, page) {
      let id = (type == 'defi' ? 'D' : 'T') + (++stateCOF.missionDraftId);
      let principauxSet = new Set(principaux.map(function(p){return p.charId;}));
      let disponibles = page.map(function(p) {
        return {tokenId:p.tokenId,charId:p.charId,nom:p.nom,secondaire:p.secondaire,
          principal:principauxSet.has(p.charId), selected:principauxSet.has(p.charId)};
      });
      let d = {
        id:id,type:type,pageId:pageId,nom:type=='defi'?'Défi':'Test collectif',seuil:15,
        tests:['DEX'], disponibles:disponibles,
        succesRequis:4,echecsMax:2,maxParPJ:2
      };
      cofMissionDrafts()[id] = d;
      if (callback) callback(d);
    });
  }

